// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.Join;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.explanation.TelemetryMetricNames;
import org.junit.jupiter.api.Test;

class CascadesPlanProvenanceAnnotatorTest {

	@Test
	void selectedTreeReportsZeroCartesianWorkForConnectedJoins() {
		SimpleValueFactory values = SimpleValueFactory.getInstance();
		StatementPattern left = pattern(values, "shared", "urn:left", "leftValue", 4.0d);
		StatementPattern right = pattern(values, "shared", "urn:right", "rightValue", 5.0d);
		Join plan = new Join(left, right);

		CascadesPlanProvenanceAnnotator.annotate(plan, provenance(2.0d, 11.0d));

		assertEquals(0.0d,
				plan.getDoubleMetricPlanned(TelemetryMetricNames.PLANNED_COST_CARTESIAN_WORK_ROWS));
	}

	@Test
	void selectedTreeReportsCartesianProductForDisconnectedJoins() {
		SimpleValueFactory values = SimpleValueFactory.getInstance();
		StatementPattern left = pattern(values, "left", "urn:left", "leftValue", 4.0d);
		StatementPattern right = pattern(values, "right", "urn:right", "rightValue", 5.0d);
		Join plan = new Join(left, right);

		CascadesPlanProvenanceAnnotator.annotate(plan, provenance(20.0d, 29.0d));

		assertEquals(20.0d,
				plan.getDoubleMetricPlanned(TelemetryMetricNames.PLANNED_COST_CARTESIAN_WORK_ROWS));
	}

	@Test
	void selectedTreeChargesBindinglessOneRowGuardOnce() {
		SimpleValueFactory values = SimpleValueFactory.getInstance();
		StatementPattern guard = new StatementPattern(
				Var.of("_guardSubject", values.createIRI("urn:subject"), true),
				Var.of("_guardPredicate", values.createIRI("urn:type"), true),
				Var.of("_guardObject", values.createIRI("urn:Class"), true));
		guard.setResultSizeEstimate(1.0d);
		StatementPattern input = pattern(values, "shared", "urn:input", "value", 100.0d);
		Join plan = new Join(guard, input);

		CascadesPlanProvenanceAnnotator.annotate(plan, provenance(100.0d, 102.0d));

		double cartesianWork = plan
				.getDoubleMetricPlanned(TelemetryMetricNames.PLANNED_COST_CARTESIAN_WORK_ROWS);
		assertTrue(cartesianWork >= 0.0d && cartesianWork <= 1.0d);
	}

	@Test
	void originatingCostEventRemainsAuthoritativeAtAnnotatedRoot() {
		SimpleValueFactory values = SimpleValueFactory.getInstance();
		StatementPattern plan = pattern(values, "subject", "urn:predicate", "object", 7.0d);
		plan.setCostEstimate(11.0d);
		plan.setDoubleMetricPlanned(TelemetryMetricNames.PLANNED_CARDINALITY_ROWS, 7.0d);
		plan.setDoubleMetricPlanned(TelemetryMetricNames.PLANNED_WORK_ROWS, 11.0d);
		plan.setDoubleMetricPlanned(TelemetryMetricNames.PLANNED_COST_WORK_ROWS, 11.0d);
		plan.setDoubleMetricPlanned("optimizer.costEventOrdinal", 3.0d);
		plan.setDoubleMetricPlanned("optimizer.costEventRows", 7.0d);
		plan.setDoubleMetricPlanned("optimizer.costEventWorkRows", 11.0d);
		plan.setStringMetricPlanned("optimizer.costEventDigest", "immutable-event");

		CascadesPlanProvenanceAnnotator.annotate(plan, provenance(101.0d, 303.0d));

		assertEquals(7.0d, plan.getResultSizeEstimate());
		assertEquals(11.0d, plan.getCostEstimate());
		assertEquals(7.0d,
				plan.getDoubleMetricPlanned(TelemetryMetricNames.PLANNED_CARDINALITY_ROWS));
		assertEquals(11.0d,
				plan.getDoubleMetricPlanned(TelemetryMetricNames.PLANNED_WORK_ROWS));
		assertEquals(11.0d,
				plan.getDoubleMetricPlanned(TelemetryMetricNames.PLANNED_COST_WORK_ROWS));
		assertEquals(303.0d,
				plan.getDoubleMetricPlanned(TelemetryMetricNames.PLANNED_OBJECTIVE_SCORE));
	}

	private static StatementPattern pattern(SimpleValueFactory values, String subject, String predicate,
			String object, double rows) {
		StatementPattern pattern = new StatementPattern(Var.of(subject), Var.of(predicate, values.createIRI(predicate)),
				Var.of(object));
		pattern.setResultSizeEstimate(rows);
		return pattern;
	}

	private static PlanProvenance provenance(double rows, double workRows) {
		CostVector cost = CostVector.ofRowsAndWork(rows, workRows,
				QErrorInterval.exact(rows, "selected-tree-test"));
		return new PlanProvenance(1, 1, "Join", "selected-tree-test", RuleKind.IMPLEMENTATION, List.of(), null, cost,
				null, null, List.of(), List.of(), false, "");
	}
}
